import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang3.ArrayUtils.add(T[] array, T element)
 */
public class ArrayUtils_add_TriageGen1Test {







    @Test
    public void testAdd_WithNullArrayAndNullElement() {
        // This tests the branch: else { type = Object.class; }
        // Since the method tries to cast the newArray to T[], 
        // and T is inferred as Object when both are null.
        Object[] input = null;
        Object element = null;
        Object[] result = ArrayUtils.add(input, element);

        assertNotNull(result);
        assertEquals(1, result.length);
        assertNull(result[0]);
    }






}

